import java.io.*;import java.util.*;import org.jf.dexlib2.*;import org.jf.dexlib2.iface.*;import org.jf.dexlib2.iface.reference.*;import org.jf.dexlib2.dexbacked.*;
public class AuditDesugarRefs{
 static Map<String,ClassDef> defs=new HashMap<>();
 static String key(MethodReference m){return m.getName()+m.getParameterTypes().toString()+m.getReturnType();}
 static String descriptor(Class<?> c){return c.isPrimitive()?(c==void.class?"V":c==boolean.class?"Z":c==byte.class?"B":c==char.class?"C":c==short.class?"S":c==int.class?"I":c==long.class?"J":c==float.class?"F":"D"):c.isArray()?c.getName().replace('.','/'):"L"+c.getName().replace('.','/')+";";}
 static boolean external(String cl,MethodReference m){try{Class<?> c=Class.forName(cl.substring(1,cl.length()-1).replace('/','.'));for(java.lang.reflect.Method d:c.getMethods()){List<String> ps=new ArrayList<>();for(Class<?> p:d.getParameterTypes())ps.add(descriptor(p));if(d.getName().equals(m.getName())&&ps.toString().equals(m.getParameterTypes().toString())&&descriptor(d.getReturnType()).equals(m.getReturnType()))return true;}}catch(Throwable e){}return false;}
 static boolean has(String cl,MethodReference m,Set<String> seen){if(!seen.add(cl))return false;ClassDef c=defs.get(cl);if(c==null)return external(cl,m);for(Method d:c.getMethods())if(key(d).equals(key(m)))return true;if(c.getSuperclass()!=null&&has(c.getSuperclass(),m,seen))return true;for(String it:c.getInterfaces())if(has(it,m,seen))return true;return false;}
 public static void main(String[] a)throws Exception{var z=DexFileFactory.loadDexContainer(new File(a[0]),Opcodes.forApi(28));List<DexBackedDexFile> files=new ArrayList<>();for(String n:z.getDexEntryNames()){DexBackedDexFile f=(DexBackedDexFile)z.getEntry(n).getDexFile();files.add(f);for(ClassDef c:f.getClasses())if(defs.put(c.getType(),c)!=null)throw new AssertionError("Duplicate "+c.getType());}int count=0;Set<String> bad=new TreeSet<>();for(DexBackedDexFile f:files)for(MethodReference m:f.getMethodSection()){if(!m.getDefiningClass().startsWith("Lj$/"))continue;count++;if(!has(m.getDefiningClass(),m,new HashSet<>()))bad.add(m.toString());}System.out.println("j$ method references inspected="+count+" unresolved="+bad.size());for(String s:bad)System.out.println(s);if(!bad.isEmpty())throw new AssertionError("Unresolved j$ methods");}
}
